    @Test
    fun `tracks the reference filter to the microsecond`() {
        val f = ClockKalmanFilter()
        rows.forEachIndexed { i, r ->
            f.processTimeResponse(r.t1, r.t2, r.t3, r.t4)
            val off = f.localToServerUs(r.t4) - r.t4  // offset at the update instant
            assertTrue(abs(f.serverToLocalUs(r.probeServer) - r.probeClient) <= 1L,
                "sample $i: compute_client_time ${f.serverToLocalUs(r.probeServer)} vs ${r.probeClient}")
            assertTrue(abs(f.errorUs() - r.error) <= 1L, "sample $i: error ${f.errorUs()} vs ${r.error}")
            assertTrue(abs(off - Math.round(r.offset)) <= 1L, "sample $i: offset $off vs ${r.offset}")
        }
        assertEquals(rows.size, f.sampleCount.coerceAtMost(rows.size))
    }
